def make_society_words():
    words = []
    subs = ["society_festivals", "society_politics", "society_media", "society_religion", "society_history"]
    for i, w in enumerate(society_data):
        sub = subs[i // 50]
        words.append((w[0], w[1], w[2], f"[{w[0].lower()}]", w[3], w[4], w[5], w[6], "society", sub, w[7]))
    return words

SOCIETY_WORDS = make_society_words()
print("Society words generated:", len(SOCIETY_WORDS))
